// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;

    // allow the contract to receive the transfer from withdraw()
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        // withdraw() must be called by the owner (the deployer = this test contract)
        vm.assume(msg.sender == address(this) || true);
        amount = bound(amount, 0, type(uint256).max / 4);
        // seed must be strictly positive so the mutant provably leaves a nonzero balance
        seed = bound(seed, 1, type(uint256).max / 4);

        // seed the contract with a balance (simulating prior deposits)
        vm.deal(address(c), seed);
        // fund the owner so it can attach `amount` to the withdraw call
        vm.deal(address(this), amount);

        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        c.withdraw{value: amount}();

        // Rule: the reference drains the ENTIRE contract balance (seed + attached value)
        // on any owner withdraw(), leaving address(c).balance == 0.
        // The mutant only sends msg.value, so `seed` remains in the contract.
        assertTrue(address(c).balance == 0, "withdraw must drain whole balance");
    }
}
